() => {
  // find a node row containing 测试一队
  const all = Array.from(document.querySelectorAll('div,li,tr'));
  const row = all.find(e => e.innerText && e.innerText.trim().startsWith('测试一队') && e.innerText.length < 40 && e.querySelectorAll('button').length > 0 && e.querySelectorAll('button').length < 8);
  if (!row) return { found: false };
  const btns = Array.from(row.querySelectorAll('button'));
  const before = btns.map(b => ({ t: b.getAttribute('title') || b.textContent.trim() || b.getAttribute('aria-label'), op: getComputedStyle(b).opacity, vis: getComputedStyle(b).visibility, disp: getComputedStyle(b).display }));
  // simulate hover
  row.dispatchEvent(new MouseEvent('mouseover', { bubbles: true }));
  row.dispatchEvent(new MouseEvent('mouseenter', { bubbles: true }));
  const after = Array.from(row.querySelectorAll('button')).map(b => ({ t: b.getAttribute('title') || b.textContent.trim() || b.getAttribute('aria-label'), op: getComputedStyle(b).opacity, vis: getComputedStyle(b).visibility, disp: getComputedStyle(b).display }));
  return { found: true, rowText: row.innerText.replace(/\n/g,'|').slice(0,80), before, after };
}

